index 7918ebb508f9..f6454b106293 100644
--- a/drivers/gpu/nova-core/gpu.rs
+++ b/drivers/gpu/nova-core/gpu.rs
@@ -314,7 +314,7 @@ fn drop(self: Pin<&mut Self>) {
             .as_ref()
             .get_ref()
             .unload(
-                GspBootContext {
+                &GspBootContext {
                     pdev: device,
                     bar,
                     chipset: this.spec.chipset,
